package cn.zhigeng.app;
import android.app.*;import android.os.*;import android.net.Uri;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.graphics.drawable.GradientDrawable;import android.content.res.ColorStateList;import android.view.*;import android.widget.*;

/** Local PDF pages with the same quiet, retractable reading controls. */
public class PdfActivity extends Activity {
    private PdfRenderer renderer;private ParcelFileDescriptor fd;private ImageView image;private TextView number,position;private LinearLayout controls;private FrameLayout root;private int page;private String id;private Bitmap bitmap;private boolean visible;
    private static final int PAPER=0xfff7f3e9,INK=0xff303136,MUTED=0xff8a8c91,GREEN=0xff3674d9;
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(false);return t;}
    private TextView button(String s,Runnable run){TextView v=label(s,14,GREEN);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(48));GradientDrawable bg=new GradientDrawable();bg.setColor(0xfff1f2f4);bg.setCornerRadius(dp(12));v.setBackground(bg);v.setOnClickListener(w->run.run());return v;}
    private void immersive(){getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}
    @Override public void onCreate(Bundle state){super.onCreate(state);immersive();root=new FrameLayout(this);root.setBackgroundColor(PAPER);LinearLayout book=new LinearLayout(this);book.setOrientation(1);number=label("本地 PDF",11,MUTED);number.setGravity(Gravity.CENTER);book.addView(number,new LinearLayout.LayoutParams(-1,dp(38)));ScrollView scroll=new ScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);image.setContentDescription("PDF 正文，轻点显示阅读菜单");image.setOnClickListener(v->toggle());scroll.addView(image);book.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView note=label("轻点书页显示菜单",11,MUTED);note.setGravity(Gravity.CENTER);book.addView(note,new LinearLayout.LayoutParams(-1,dp(30)));root.addView(book,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
        controls=new LinearLayout(this);controls.setOrientation(1);controls.setPadding(dp(24),dp(22),dp(24),dp(28));GradientDrawable panel=new GradientDrawable();panel.setColor(0xfffffefa);panel.setCornerRadius(dp(24));controls.setBackground(panel);position=label("阅读进度",14,INK);controls.addView(position);SeekBar seek=new SeekBar(this);seek.setContentDescription("PDF 页码");seek.setProgressTintList(ColorStateList.valueOf(GREEN));seek.setThumbTintList(ColorStateList.valueOf(GREEN));controls.addView(seek,new LinearLayout.LayoutParams(-1,dp(48)));LinearLayout turns=new LinearLayout(this);turns.addView(button("‹ 上一页",()->{if(page>0){page--;show();seek.setProgress(page);scroll.scrollTo(0,0);}}),new LinearLayout.LayoutParams(0,dp(48),1));turns.addView(button("下一页 ›",()->{if(renderer!=null&&page<renderer.getPageCount()-1){page++;show();seek.setProgress(page);scroll.scrollTo(0,0);}}),new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(turns);LinearLayout actions=new LinearLayout(this);actions.setPadding(0,dp(16),0,0);actions.addView(button("书架",this::finish),new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(button("记书签",()->{getSharedPreferences("reader",MODE_PRIVATE).edit().putInt(id+":pdfBookmark",page).apply();Toast.makeText(this,"书签已保存",0).show();}),new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(button("回书签",()->{page=Math.min(getSharedPreferences("reader",MODE_PRIVATE).getInt(id+":pdfBookmark",0),renderer.getPageCount()-1);show();seek.setProgress(page);scroll.scrollTo(0,0);}),new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(button("收起",this::toggle),new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(actions);root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));controls.setVisibility(View.GONE);
        try{id=getIntent().getStringExtra("uri");fd=getContentResolver().openFileDescriptor(Uri.parse(id),"r");renderer=new PdfRenderer(fd);page=Math.max(0,Math.min(getSharedPreferences("reader",MODE_PRIVATE).getInt(id+":pdfPage",0),renderer.getPageCount()-1));seek.setMax(renderer.getPageCount()-1);seek.setProgress(page);show();}catch(Exception e){controls.setVisibility(View.GONE);new AlertDialog.Builder(this).setMessage("PDF 打开失败，请检查文件或重新导入。").setPositiveButton("返回",(d,w)->finish()).setOnCancelListener(d->finish()).show();}seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(user)position.setText("跳转至第 "+(p+1)+" 页");}public void onStopTrackingTouch(SeekBar s){if(renderer!=null){page=s.getProgress();show();scroll.scrollTo(0,0);}}});}
    private void toggle(){visible=!visible;controls.setVisibility(visible?View.VISIBLE:View.GONE);}
    private void show(){try(PdfRenderer.Page p=renderer.openPage(page)){int width=Math.min(1600,getResources().getDisplayMetrics().widthPixels),height=Math.min(6000,Math.max(1,Math.round(width*p.getHeight()/(float)p.getWidth())));Bitmap next=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);next.eraseColor(Color.WHITE);p.render(next,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(next);if(bitmap!=null)bitmap.recycle();bitmap=next;number.setText("PDF  ·  "+(page+1)+" / "+renderer.getPageCount());position.setText("第 "+(page+1)+" 页，共 "+renderer.getPageCount()+" 页");getSharedPreferences("reader",MODE_PRIVATE).edit().putInt(id+":pdfPage",page).apply();}catch(Exception e){Toast.makeText(this,"该页无法显示",0).show();}}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)immersive();}
    @Override public void onBackPressed(){if(visible)toggle();else super.onBackPressed();}
    @Override protected void onDestroy(){image.setImageDrawable(null);if(bitmap!=null)bitmap.recycle();if(renderer!=null)renderer.close();try{if(fd!=null)fd.close();}catch(Exception ignored){}super.onDestroy();}
}
